import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import report from '@/lib/field-report.json';

// The Field Report summary the web app shows (docs/FIELD_REPORT.md). It is
// generated by `node scripts/wild-scan.mjs report --set fixtures/wild-scan-round2
// --previous fixtures/wild-scan --dev fixtures/wild-scan/dev-rerun-round2-rules`; these checks keep its
// numbers consistent with each other and with the data it was made from.
const root = fileURLToPath(new URL('../../../../', import.meta.url));
const sum = (o: Record<string, number>) => Object.values(o).reduce((a, b) => a + b, 0);
const raw = readFileSync(`${root}apps/web/src/lib/field-report.json`, 'utf8');

describe('field-report.json', () => {
  it('is small and its counts add up', () => {
    expect(Buffer.byteLength(raw)).toBeLessThan(20 * 1024);
    expect(sum(report.findings.bySeverity)).toBe(report.findings.total);
    expect(sum(report.findings.byRule)).toBe(report.findings.total);
    expect(report.findings.bySeverity.critical + report.findings.bySeverity.high).toBe(report.highCritical.findings);
    expect(report.highCritical.triaged).toBe(report.highCritical.findings);
    expect(sum(report.highCritical.perFinding)).toBe(report.highCritical.findings);
    expect(sum(report.highCritical.perIssue)).toBe(report.highCritical.issues);
    expect(sum(report.reposByPool)).toBe(report.repos);
    expect(report.reposWithFindings).toBeLessThanOrEqual(report.repos);
    const { perIssue, issues } = report.highCritical;
    expect(report.precision.value).toBeCloseTo((100 * perIssue['true-positive']) / issues, 1);
    expect(report.precision.withDebatable).toBeCloseTo((100 * (perIssue['true-positive'] + perIssue.debatable)) / issues, 1);
  });

  it('lists every true finding (at most five) with a link to the pinned commit', () => {
    expect(report.topTrue.length).toBe(report.highCritical.perIssue['true-positive']);
    expect(report.topTrue.length).toBeLessThanOrEqual(5);
    for (const t of [...report.topTrue, ...report.notableDebatable]) {
      expect(t.fileUrl).toMatch(/^https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/blob\/[0-9a-f]{40}\/.+#L\d+$/);
      expect(t.ruleId).toMatch(/^EX-\d{3}$/);
      expect(t.description.length).toBeGreaterThan(20);
    }
    // Round 2 has no true positives, so the JSON's inferred type for topTrue is an empty array.
    for (const t of report.topTrue as Array<{ label: string }>) expect(t.label).toBe('true-positive');
    for (const t of report.notableDebatable) expect(t.label).toBe('debatable');
  });

  it('never carries a credential', () => {
    expect(raw).not.toMatch(/github_pat_[A-Za-z0-9_]{20,}|ghp_[A-Za-z0-9]{30,}|sk-ant-[A-Za-z0-9_-]{30,}|AKIA[0-9A-Z]{16}/);
  });

  it('describes round 2 (a fresh held-out set) first, with round 1 kept for comparison', () => {
    expect(report.round).toBe(2);
    expect(report.heldOut).toBe(true);
    const r1 = report.round1;
    expect(sum(r1.highCritical.perIssue)).toBe(r1.highCritical.issues);
    expect(sum(r1.highCritical.perFinding)).toBe(r1.highCritical.findings);
    expect(r1.precision.value).toBeCloseTo((100 * r1.highCritical.perIssue['true-positive']) / r1.highCritical.issues, 1);
    expect(report.round1DevRerun.note).toMatch(/not a measure/);
  });

  const r1results = `${root}fixtures/wild-scan/results.json`;
  const r1triage = `${root}fixtures/wild-scan/triage.json`;
  it.runIf(existsSync(r1results) && existsSync(r1triage))('round 1 numbers match the round-1 results and triage', () => {
    const state = JSON.parse(readFileSync(r1results, 'utf8')) as { repos: Record<string, { filesScanned: number; findings: { severity: string }[] }> };
    const tri = JSON.parse(readFileSync(r1triage, 'utf8')) as { labels: { label: string }[] };
    const repos = Object.values(state.repos);
    expect(repos.length).toBe(report.round1.repos);
    expect(repos.flatMap((r) => r.findings).length).toBe(report.round1.findings.total);
    expect(tri.labels.length).toBe(report.round1.highCritical.findings);
  });

  const results = `${root}fixtures/wild-scan-round2/results.json`;
  const triage = `${root}fixtures/wild-scan-round2/triage.json`;
  it.runIf(existsSync(results) && existsSync(triage))('matches the round-2 scan results and the triage it was made from', () => {
    type Finding = { ruleId: string; severity: string; span: string };
    const state = JSON.parse(readFileSync(results, 'utf8')) as { repos: Record<string, { status: string; filesScanned: number; findings: Finding[] }> };
    const tri = JSON.parse(readFileSync(triage, 'utf8')) as { labels: { label: string }[] };
    const repos = Object.values(state.repos);
    expect(repos.length).toBe(report.repos);
    expect(repos.every((r) => r.status === 'ok')).toBe(true);
    expect(repos.reduce((a, r) => a + r.filesScanned, 0)).toBe(report.files);
    const all = repos.flatMap((r) => r.findings);
    expect(all.length).toBe(report.findings.total);
    expect(all.filter((f) => f.severity === 'critical' || f.severity === 'high').length).toBe(tri.labels.length);
    expect(tri.labels.filter((l) => l.label === 'true-positive').length).toBe(report.highCritical.perFinding['true-positive']);
    expect(tri.labels.filter((l) => l.label === 'debatable').length).toBe(report.highCritical.perFinding.debatable);
    // Possible secrets are stored redacted.
    for (const f of all.filter((x) => x.ruleId === 'EX-011')) expect(f.span).toMatch(/^\[redacted: \d+ characters\]$/);
  });
});
